) as v(ing, form, unit, g, src, note)
join ingredients i on i.canonical_name = v.ing
left join units u on u.name = v.unit
where v.unit = 'each' or u.id is not null
on conflict (ingredient_id, form, (coalesce(unit_id, 0))) do update set
  grams_per_unit = excluded.grams_per_unit, source = excluded.source, note = excluded.note;

insert into prep_rules (kind, pattern, ingredient_id, factor, note)
select 'grams_factor', '\mfr(y|ied|ying)\M', i.id, 0.15,
       'proposed: a frying bath is mostly discarded; the food keeps about 15 percent (USDA/industry range 8 to 25)'
from ingredients i where i.canonical_name = 'vegetable oil'
  and not exists (select 1 from prep_rules r where r.kind = 'grams_factor' and r.ingredient_id = i.id and r.pattern = '\mfr(y|ied|ying)\M');

insert into prep_rules (kind, pattern, form, note)
select 'form', '\m(drained|rinsed)\M', 'canned',
       'proposed: a drained/rinsed line is the canned product; only applies to ingredients that have a canned form'
where not exists (select 1 from prep_rules r where r.kind = 'form' and r.pattern = '\m(drained|rinsed)\M' and r.ingredient_id is null);
